mapper.select:
SELECT to_char(s.created_at AT TIME ZONE #{query.Timezone}, 'YYYY-MM-DD') AS date,
       s.agent_external_id AS agent_id,
       COALESCE(a.name, s.agent_external_id) AS agent_name,
       COUNT(*) AS session_count,
       COUNT(*) FILTER (WHERE EXISTS (
           SELECT 1 FROM session_events e
           WHERE e.organization_uuid = #{query.OrganizationUUID}
           AND e.workspace_uuid = #{query.WorkspaceUUID}
           AND e.session_uuid = s.uuid
           AND e.created_at >= #{query.Start} AND e.created_at < #{query.End}
           AND e.deleted_at IS NULL
           AND (
               (e.event_type = 'session.status_idle' AND e.payload->'stop_reason'->>'type' = 'retries_exhausted')
               OR (e.event_type = 'session.error' AND e.payload->'error'->'retry_status'->>'type' IN ('exhausted', 'terminal'))
           )
       )) AS failed_session_count,
       MAX(s.created_at) AS last_run_at
FROM sessions s
LEFT JOIN agents a ON a.uuid = s.agent_uuid AND a.workspace_uuid = #{query.WorkspaceUUID}
WHERE s.organization_uuid = #{query.OrganizationUUID} AND s.workspace_uuid = #{query.WorkspaceUUID}
AND s.created_at >= #{query.Start} AND s.created_at < #{query.End}
AND s.deleted_at IS NULL
GROUP BY date, s.agent_external_id, a.name
ORDER BY date, s.agent_external_id
